(function () {
'use strict';
var API = 'search-api.php';
var MIN = 2;
var isMac = /Mac|iPhone|iPad/.test(navigator.platform || navigator.userAgent);
function esc(s) {
return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
});
}
function mark(text, words) {
var html = esc(text);
if (!words.length) return html;
var re = new RegExp('(' + words.map(function (w) { return esc(w).replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }).join('|') + ')', 'gi');
return html.replace(re, '<mark>$1</mark>');
}
function Search(input, panel, opts) {
var self = this;
var timer = null, ctrl = null, seq = 0, active = -1, links = [];
opts = opts || {};
function show(state) {
panel.hidden = !state;
input.setAttribute('aria-expanded', state ? 'true' : 'false');
if (opts.onToggle) opts.onToggle(state);
}
function setActive(i) {
if (!links.length) return;
active = (i + links.length) % links.length;
links.forEach(function (a, k) { a.setAttribute('aria-selected', k === active ? 'true' : 'false'); });
input.setAttribute('aria-activedescendant', links[active].id);
links[active].scrollIntoView({ block: 'nearest' });
}
function message(html, cls) {
panel.innerHTML = '<div class="gs-msg ' + (cls || '') + '">' + html + '</div>';
links = []; active = -1;
input.removeAttribute('aria-activedescendant');
show(true);
}
function render(d, q) {
var words = q.split(/\s+/).filter(Boolean);
if (!d.total) {
message('<span class="gs-msg__icon" aria-hidden="true">' + (opts.searchIcon || '') + '</span>'
+ '<strong>Aucun résultat pour « ' + esc(q) + ' »</strong>'
+ '<span>Recherche dans : ' + esc((d.scopes || []).join(', ')) + '.</span>'
+ '<span>Vérifiez l\'orthographe ou essayez un N° de reçu, de facture, de suivi ou un téléphone.</span>', 'gs-msg--empty');
return;
}
var uid = input.id || 'gs';
var html = '', n = 0;
d.categories.forEach(function (c) {
html += '<section class="gs-group" aria-label="' + esc(c.label) + '">'
+ '<h3 class="gs-group__title"><span class="gs-group__icon gs-group__icon--' + esc(c.key) + '" aria-hidden="true">' + c.icon + '</span>'
+ esc(c.label) + '<span class="gs-group__count">' + c.count + '</span></h3><ul role="presentation">';
c.items.forEach(function (it) {
html += '<li role="presentation"><a class="gs-item" role="option" aria-selected="false" id="' + uid + '-opt-' + (n++) + '" href="' + esc(it.url) + '">'
+ '<span class="gs-item__icon gs-group__icon--' + esc(c.key) + '" aria-hidden="true">' + (it.icon || c.icon) + '</span>'
+ '<span class="gs-item__body"><span class="gs-item__title">' + mark(it.title, words) + '</span>'
+ (it.sub ? '<span class="gs-item__sub">' + mark(it.sub, words) + '</span>' : '') + '</span>'
+ (it.meta ? '<span class="gs-item__meta">' + esc(it.meta) + '</span>' : '')
+ (it.badge ? '<span class="badge badge--' + esc(it.badge.tone) + ' gs-item__badge">' + esc(it.badge.label) + '</span>' : '')
+ '</a></li>';
});
html += '</ul>';
if (c.more && c.count > c.items.length) {
html += '<a class="gs-more gs-item" role="option" aria-selected="false" id="' + uid + '-opt-' + (n++) + '" href="' + esc(c.more) + '">'
+ 'Voir les ' + c.count + ' résultats dans « ' + esc(c.label) + ' »</a>';
}
html += '</section>';
});
panel.innerHTML = html;
links = [].slice.call(panel.querySelectorAll('.gs-item'));
active = -1;
setActive(0);
show(true);
}
function run(q) {
var mine = ++seq;
if (ctrl) ctrl.abort();
ctrl = 'AbortController' in window ? new AbortController() : null;
input.closest('[data-gs-field]').classList.add('is-loading');
fetch(API + '?q=' + encodeURIComponent(q), { credentials: 'same-origin', headers: { Accept: 'application/json' }, signal: ctrl ? ctrl.signal : undefined })
.then(function (r) {
if (r.status === 401) throw new Error('Session expirée : rechargez la page pour vous reconnecter.');
return r.json().then(function (d) { if (!r.ok) throw new Error(d.error || 'Recherche indisponible.'); return d; });
})
.then(function (d) { if (mine === seq) render(d, q); })
.catch(function (e) { if (mine === seq && e.name !== 'AbortError') message(esc(e.message || 'Recherche indisponible.'), 'gs-msg--error'); })
.then(function () { if (mine === seq) input.closest('[data-gs-field]').classList.remove('is-loading'); });
}
function open(a, newTab) {
if (!a) return;
if (newTab) { window.open(a.href, '_blank', 'noopener'); return; }
window.location.href = a.href;
}
input.addEventListener('input', function () {
var q = input.value.trim();
clearTimeout(timer);
if (q.length < MIN) {
if (opts.idle) { panel.innerHTML = opts.idle; links = []; show(opts.keepOpen === true); }
else show(false);
if (ctrl) ctrl.abort();
seq++;
input.closest('[data-gs-field]').classList.remove('is-loading');
return;
}
timer = setTimeout(function () { run(q); }, 180);
});
input.addEventListener('keydown', function (e) {
if (e.key === 'ArrowDown') { e.preventDefault(); setActive(active + 1); }
else if (e.key === 'ArrowUp') { e.preventDefault(); setActive(active - 1); }
else if (e.key === 'Enter') {
e.preventDefault();
if (links.length) open(links[active >= 0 ? active : 0], e.ctrlKey || e.metaKey);
} else if (e.key === 'Escape') {
if (opts.onEscape) { e.preventDefault(); opts.onEscape(); }
else if (!panel.hidden) { e.preventDefault(); show(false); }
}
});
panel.addEventListener('mousemove', function (e) {
var a = e.target.closest('.gs-item');
if (a && links.indexOf(a) !== active) setActive(links.indexOf(a));
});
self.reset = function () { input.value = ''; clearTimeout(timer); seq++; if (ctrl) ctrl.abort(); input.dispatchEvent(new Event('input')); };
self.hide = function () { show(false); };
self.refresh = function () { if (input.value.trim().length >= MIN) run(input.value.trim()); };
}
var searchIcon = (document.querySelector('[data-gs-open] svg, [data-gs-field] svg') || {}).outerHTML || '';
var palette = document.querySelector('[data-gs-palette]');
var paletteSearch = null, lastFocus = null;
if (palette) {
var pInput = palette.querySelector('[data-gs-input]');
var pPanel = palette.querySelector('[data-gs-results]');
var idle = pPanel.innerHTML;   // aide affichée tant que rien n'est saisi
var openPalette = function (prefill) {
lastFocus = document.activeElement;
palette.hidden = false;
document.documentElement.classList.add('gs-lock');
if (typeof prefill === 'string') { pInput.value = prefill; }
pInput.focus();
pInput.select();
if (pInput.value.trim().length >= MIN) paletteSearch.refresh();
};
var closePalette = function () {
palette.hidden = true;
document.documentElement.classList.remove('gs-lock');
if (lastFocus && lastFocus.focus) lastFocus.focus();
};
paletteSearch = new Search(pInput, pPanel, { idle: idle, keepOpen: true, onEscape: closePalette, searchIcon: searchIcon });
document.querySelectorAll('[data-gs-open]').forEach(function (b) {
b.addEventListener('click', function () { openPalette(); });
});
palette.addEventListener('mousedown', function (e) { if (e.target === palette || e.target.hasAttribute('data-gs-close')) { e.preventDefault(); closePalette(); } });
palette.addEventListener('keydown', function (e) { if (e.key === 'Tab') { e.preventDefault(); pInput.focus(); } });
window.GTCSearch = { open: openPalette, close: closePalette };
}
var hub = document.querySelector('[data-gs-inline]');
var hubSearch = null;
if (hub) {
var hInput = hub.querySelector('[data-gs-input]');
var hPanel = hub.querySelector('[data-gs-results]');
hubSearch = new Search(hInput, hPanel, { searchIcon: searchIcon, onToggle: function (on) { hub.classList.toggle('is-open', on); } });
document.addEventListener('mousedown', function (e) { if (!hub.contains(e.target)) hubSearch.hide(); });
hInput.addEventListener('focus', function () { if (hInput.value.trim().length >= MIN && hPanel.innerHTML) hubSearch.refresh(); });
}
document.addEventListener('keydown', function (e) {
var k = (e.key || '').toLowerCase();
var typing = /^(input|textarea|select)$/i.test(e.target.tagName) || e.target.isContentEditable;
if ((k === 'k' && (e.ctrlKey || e.metaKey) && !e.altKey && !e.shiftKey) || (k === '/' && !typing && !e.ctrlKey && !e.metaKey)) {
e.preventDefault();
if (hub && hub.offsetParent !== null && (!palette || palette.hidden)) {
hub.querySelector('[data-gs-input]').focus();
hub.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
} else if (palette) {
palette.hidden ? window.GTCSearch.open() : window.GTCSearch.close();
}
}
});
if (isMac) document.querySelectorAll('[data-gs-kbd]').forEach(function (k) { k.textContent = '⌘ K'; });
})();
